#!/usr/bin/env python3
"""Bounded CSV/Zstandard capture decoding for the offline campaign."""
import base64
import binascii
import csv
import io

import zstandard as zstd

from common import (COLUMNS, MAX_DECODED, MAX_DECOMPRESSED, MAX_FIELD_BYTES,
                    MAX_RECORDS, MAX_WINDOW, CaptureError)
from ledger import parse_record


def _complete_frames(data):
    """Validate complete dictionary-free Zstandard framing."""
    at = 0
    size = len(data)
    while at < size:
        if at + 4 > size:
            raise CaptureError('truncated Zstandard magic')
        magic = int.from_bytes(data[at:at + 4], 'little')
        if 0x184d2a50 <= magic <= 0x184d2a5f:
            if at + 8 > size:
                raise CaptureError('truncated skippable frame')
            frame_size = int.from_bytes(data[at + 4:at + 8], 'little')
            at += 8 + frame_size
            if at > size:
                raise CaptureError('truncated skippable frame')
            continue
        if magic != 0xfd2fb528 or at + 5 > size:
            raise CaptureError('invalid Zstandard frame magic')

        flag = data[at + 4]
        # Bit 3 is reserved; bit 4 is an unused header bit and is ignored.
        if flag & 0x08:
            raise CaptureError('reserved Zstandard frame bit')
        single = bool(flag & 0x20)
        dictionary_len = (0, 1, 2, 4)[flag & 0x03]
        content_size_len = (1 if single else 0, 2, 4, 8)[flag >> 6]
        header_len = 5 + (0 if single else 1) + dictionary_len + content_size_len
        if at + header_len > size:
            raise CaptureError('truncated Zstandard header')
        try:
            parameters = zstd.get_frame_parameters(data[at:at + header_len])
        except zstd.ZstdError:
            raise CaptureError('invalid Zstandard header') from None
        if parameters.dict_id or parameters.window_size > MAX_WINDOW:
            raise CaptureError('unsupported dictionary or window')

        cursor = at + header_len
        while True:
            if cursor + 3 > size:
                raise CaptureError('truncated Zstandard block header')
            block = int.from_bytes(data[cursor:cursor + 3], 'little')
            cursor += 3
            kind = (block >> 1) & 3
            block_size = block >> 3
            if kind == 3:
                raise CaptureError('reserved Zstandard block type')
            cursor += 1 if kind == 1 else block_size
            if cursor > size:
                raise CaptureError('truncated Zstandard block')
            if block & 1:
                break
        if flag & 0x04:
            cursor += 4
            if cursor > size:
                raise CaptureError('truncated Zstandard checksum')
        at = cursor



def complete_frames(data):
    try:
        _complete_frames(data)
    except CaptureError:
        raise
    except Exception:
        raise CaptureError('invalid Zstandard framing') from None


def decode_chunks(chunks):
    blocks = []
    for text in chunks:
        try:
            blocks.append(base64.b64decode(text.encode('ascii'),
                                           validate=True))
        except (ValueError, UnicodeError, binascii.Error):
            raise CaptureError('invalid base64 chunk') from None
    return blocks


def decompress_zstd(data, remaining):
    """Return decompressed bytes, rejecting anything over the shared budget."""
    output = []
    used = 0
    reader = zstd.ZstdDecompressor(max_window_size=MAX_WINDOW).stream_reader(
        io.BytesIO(data), read_across_frames=True)
    try:
        while True:
            want = min(1024 * 1024, remaining - used + 1)
            chunk = reader.read(want)
            if not chunk:
                break
            used += len(chunk)
            if used > remaining:
                raise CaptureError('decompressed byte budget')
            output.append(chunk)
    except CaptureError:
        raise
    except (zstd.ZstdError, ValueError, EOFError, OSError):
        raise CaptureError('invalid Zstandard data') from None
    finally:
        try:
            reader.close()
        except Exception:
            pass
    return b''.join(output)


def capture_records(context, lookup):
    """Decode captures and return (valid_records, rejected_indices)."""
    # The parser's own field size limit is a safety net.  The protocol limit
    # applies to the parsed UTF-8 byte length, so keep the raw CSV limit above
    # the total decompressed budget to allow quoted/doubled-quote fields.
    csv.field_size_limit(MAX_DECOMPRESSED)

    records = []
    rejected = []
    decoded_total = 0
    remaining = MAX_DECOMPRESSED
    record_count = 0

    for capture_index, capture in enumerate(context['captures']):
        blocks = decode_chunks(capture['chunks'])
        decoded_total += sum(len(block) for block in blocks)
        if decoded_total > MAX_DECODED:
            raise CaptureError('decoded byte budget')
        payload = b''.join(blocks)
        del blocks

        if capture['encoding'] == 'zstd':
            complete_frames(payload)
            data = decompress_zstd(payload, remaining)
        else:
            if len(payload) > remaining:
                raise CaptureError('decompressed byte budget')
            data = payload
        remaining -= len(data)
        del payload

        try:
            text = data.decode('utf-8')
        except UnicodeError:
            raise CaptureError('invalid UTF-8') from None
        del data

        reader = csv.reader(io.StringIO(text, newline=''), strict=True)
        try:
            header = next(reader, None)
        except csv.Error:
            raise CaptureError('invalid CSV header') from None
        if header != list(COLUMNS):
            raise CaptureError('invalid CSV header')

        try:
            for ordinal, values in enumerate(reader):
                record_count += 1
                if record_count > MAX_RECORDS:
                    raise CaptureError('logical record budget')
                too_large = False
                for value in values:
                    if len(value.encode('utf-8')) > MAX_FIELD_BYTES:
                        too_large = True
                        break
                if too_large:
                    raise CaptureError('field byte budget')
                if len(values) != 14:
                    rejected.append([capture_index, ordinal])
                    continue
                try:
                    record = parse_record(values, context, lookup)
                except (ValueError, TypeError, KeyError, IndexError,
                        OverflowError):
                    rejected.append([capture_index, ordinal])
                    continue
                records.append(record)
        except csv.Error:
            raise CaptureError('invalid CSV syntax') from None

    return records, rejected


# ---------------------------------------------------------------------------
# Legacy network-bucket helper retained for the development CLI.
# ---------------------------------------------------------------------------

def record_response(networks, key, target, responder, same_is_internal=True):
    bucket = networks.setdefault(key, {'network': key, 'internal': set(),
                                       'external': set()})
    if target == responder:
        if not same_is_internal:
            return None
        role = 'internal'
    else:
        role = 'external'
    bucket[role].add(responder)
    return role
